printf '%s  %s\n' 6c69c690d4e2491255a3a12370b1143515a4d223456880e889fd24eafaea0c51 "$BUNDLE/slot_policy.py" d26f808fcce89c9d5674d69484bcbac614608761b1f2602d04ee6e5935b49aec "$BUNDLE/BUNDLE.json" | sha256sum -c - >&2
